declare module "pdf-parse" {
  interface PdfParseResult {
    numpages: number;
    numrender: number;
    info: Record<string, unknown>;
    metadata: unknown;
    version: string;
    text: string;
  }
  function pdf(dataBuffer: Buffer, options?: unknown): Promise<PdfParseResult>;
  export default pdf;
}

declare module "pdf-parse/lib/pdf-parse.js" {
  interface PdfParseResult {
    numpages: number;
    numrender: number;
    info: Record<string, unknown>;
    metadata: unknown;
    version: string;
    text: string;
  }
  function pdf(dataBuffer: Buffer, options?: unknown): Promise<PdfParseResult>;
  export default pdf;
}